from sympy import QQ, Rational, binomial, ceiling
from sympy.polys.puiseux import puiseux_ring
from sympy.polys.ring_series import rs_pow
R, x = puiseux_ring('x', QQ)
examples = [
    (x+x**2, Rational(-1, 2), 3, x**QQ(-1,2)-x**QQ(1,2)/2+3*x**QQ(3,2)/8-5*x**QQ(5,2)/16),
    (x**-3+x**-2, Rational(2, 3), 1, x**-2+2*x**-1/3-R(1)/9),
    (x**2+x**3, Rational(-1, 2), 1, x**-1-R(1)/2),
]
for p, n, prec, expected in examples:
    actual = rs_pow(p, n, x, prec)
    assert actual == expected, (actual, expected)
    print(actual.as_expr())
count = 0
for m in map(QQ, [-3, -2, -1, Rational(-1,2), 0, Rational(1,3), 1, 2, 3]):
    for d in [QQ(1,2), QQ(1), QQ(3,2)]:
        p = x**m * (1+x**d+x**(2*d))
        for n in map(Rational, [Rational(-5,3), Rational(-3,2), Rational(-1,2), Rational(1,3), Rational(1,2), Rational(2,3), Rational(3,2), Rational(5,2)]):
            shift = m * QQ(n)
            for prec in [-1, 0, 1, 2, 3]:
                expected = R.zero
                for k in range(max(0, int(ceiling((prec-shift)/d)))):
                    coefficient = sum(binomial(n,j)*binomial(j,k-j) for j in range((k+1)//2,k+1))
                    expected += QQ(coefficient)*x**(shift+k*d)
                actual = rs_pow(p, n, x, prec)
                assert actual == expected, (p, n, prec, actual, expected)
                count += 1
print(f'{count} rational-power cases passed')
for n in [Rational(1,2), Rational(3,2)]:
    assert rs_pow(R.zero, n, x, 3) == R.zero
for n in [Rational(-1,2), Rational(-3,2)]:
    try:
        rs_pow(R.zero, n, x, 3)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError('negative power of zero')
PY","yield_time_ms":1000,"max_output_tokens":2000}));
